1	import { BlockId } from "@/lib/world";
2	import { GEN } from "@/lib/world/generation";
3	import {
4	  CROP_GROWTH_CHANCE,
5	  GRASS_SPREAD_CHANCE,
6	  KELP_GROWTH_CHANCE,
7	  RANDOM_TICK_INTERVAL_SECONDS,
8	  RANDOM_TICK_RADIUS,
9	  RANDOM_TICK_SAMPLES,
10	  SAPLING_GROWTH_CHANCE
11	} from "@/lib/game/config";
12	import type { GameState } from "../state";
13	import { growTreeAt } from "./treeGrowth";
14	
15	/**
16	 * Random block ticks: on a fixed interval, sample columns near the player and
17	 * run a per-block handler on the top block. This is the growth/spread engine —
18	 * crops grow, saplings become trees, and bare dirt re-grasses. Every result is
19	 * an ordinary block edit, so it rides blockChanges and the save diff with no
20	 * extra state. The handler registry is the extension point for new behaviours.
21	 */
22	
23	type RandomTickHandler = (state: GameState, x: number, y: number, z: number, rng: () => number) => void;
24	
25	/** Advances a wheat crop one stage. Stage ids are consecutive, so +1 is the next stage. */
26	function growCrop(state: GameState, x: number, y: number, z: number, rng: () => number): void {
27	  if (rng() >= CROP_GROWTH_CHANCE) return;
28	  const next = (state.world.get(x, y, z) + 1) as BlockId;
29	  state.blockChanges.set(x, y, z, next);
30	  state.worldMeshDirty = true;
31	}
32	
33	/** A sapling sitting on soil matures into a tree. Off-soil saplings never grow. */
34	function growSapling(state: GameState, x: number, y: number, z: number, rng: () => number): void {
35	  if (rng() >= SAPLING_GROWTH_CHANCE) return;
36	  const below = state.world.get(x, y - 1, z) as BlockId;
37	  if (below !== BlockId.Grass && below !== BlockId.Dirt && below !== BlockId.Farmland) return;
38	  growTreeAt(state, x, y, z, rng);
39	}
40	
41	/** Exposed dirt re-grasses when an adjacent column's top block is grass. */
42	const GRASS_SPREAD_NEIGHBORS: ReadonlyArray<readonly [number, number]> = [
43	  [1, 0],
44	  [-1, 0],
45	  [0, 1],
46	  [0, -1]
47	];
48	function spreadGrass(state: GameState, x: number, y: number, z: number, rng: () => number): void {
49	  if (rng() >= GRASS_SPREAD_CHANCE) return;
50	  const { world } = state;
51	  for (const [dx, dz] of GRASS_SPREAD_NEIGHBORS) {
52	    const ny = world.highestSolidY(x + dx, z + dz);
53	    if (world.get(x + dx, ny, z + dz) === BlockId.Grass) {
54	      state.blockChanges.set(x, y, z, BlockId.Grass);
55	      state.worldMeshDirty = true;
56	      return;
57	    }
58	  }
59	}
60	
61	/**
62	 * A kelp stalk's top grows one block up into the water above. Growth keeps the
63	 * worldgen invariants (GEN.oceanFlora): the stalk caps at kelpMaxHeight, and
64	 * kelpSurfaceClearance water blocks must remain above the new top — kelp is a
65	 * solid block, so the clearance keeps boats and fishing casts clear of it.
66	 */
67	function growKelp(state: GameState, x: number, y: number, z: number, rng: () => number): void {
68	  if (rng() >= KELP_GROWTH_CHANCE) return;
69	  const { world } = state;
70	  const { kelpMaxHeight, kelpSurfaceClearance } = GEN.oceanFlora;
71	
72	  let height = 1;
73	  while (world.get(x, y - height, z) === BlockId.Kelp) height += 1;
74	  if (height >= kelpMaxHeight) return;
75	
76	  // The growth target plus the clearance band above it must all be water.
77	  for (let dy = 1; dy <= kelpSurfaceClearance + 1; dy += 1) {
78	    if (world.get(x, y + dy, z) !== BlockId.Water) return;
79	  }
80	  state.blockChanges.set(x, y + 1, z, BlockId.Kelp);
81	  state.worldMeshDirty = true;
82	}
83	
84	const RANDOM_TICK_HANDLERS: Partial<Record<BlockId, RandomTickHandler>> = {
85	  [BlockId.WheatStage0]: growCrop,
86	  [BlockId.WheatStage1]: growCrop,
87	  [BlockId.WheatStage2]: growCrop,
88	  // WheatStage3 has no handler — mature crops stop growing.
89	  [BlockId.Sapling]: growSapling,
90	  [BlockId.Dirt]: spreadGrass,
91	  [BlockId.Kelp]: growKelp
92	};
93	
94	export function tickRandomBlocks(state: GameState, dt: number, rng: () => number): void {
95	  state.timers.randomTickTimer += dt;
96	  if (state.timers.randomTickTimer < RANDOM_TICK_INTERVAL_SECONDS) return;
97	  state.timers.randomTickTimer = 0;
98	
99	  const { world } = state;
100	  if (state.players.size === 0) return; // an idle server room grows nothing
101	  // The sample budget splits across players (each interval stays constant-cost),
102	  // so crops grow around everyone. Single-player: the full budget around the
103	  // one player — exactly the old behavior, same rng stream.
104	  const players = [...state.players.values()];
105	  const perPlayer = Math.max(1, Math.floor(RANDOM_TICK_SAMPLES / players.length));
106	  for (const player of players) {
107	    const px = Math.floor(player.position.x);
108	    const pz = Math.floor(player.position.z);
109	    for (let i = 0; i < perPlayer; i += 1) {
110	      const x = px + Math.floor((rng() * 2 - 1) * RANDOM_TICK_RADIUS);
111	      const z = pz + Math.floor((rng() * 2 - 1) * RANDOM_TICK_RADIUS);
112	      if (!world.inBounds(x, 0, z)) continue;
113	      const y = world.highestSolidY(x, z);
114	      const handler = RANDOM_TICK_HANDLERS[world.get(x, y, z) as BlockId];
115	      if (handler) handler(state, x, y, z, rng);
116	    }
117	  }
118	}
