// Diagnostic: which random-tickable columns does seed-1337 worldgen leave
// within RANDOM_TICK_RADIUS of the e2e spawn? (Names the determinism-flake culprit.)
import { VoxelWorld, BlockId } from "/Users/hutusi/workspace/ai/david/monecraft/lib/world";
import { generateWorld, GEN } from "/Users/hutusi/workspace/ai/david/monecraft/lib/world/generation";
import { findSpawnOnLand } from "/Users/hutusi/workspace/ai/david/monecraft/lib/game/spawn";
import { RANDOM_TICK_RADIUS, RANDOM_TICK_SAMPLES, GRASS_SPREAD_CHANCE, KELP_GROWTH_CHANCE } from "/Users/hutusi/workspace/ai/david/monecraft/lib/game/config";

const world = new VoxelWorld(512, 150, 512, 1337);
generateWorld(world);
const spawn = findSpawnOnLand(world, 256, 256);
const px = Math.floor(spawn.x);
const pz = Math.floor(spawn.z);
console.log(`spawn: x=${px} z=${pz} y=${spawn.y}`);

const { kelpMaxHeight, kelpSurfaceClearance } = GEN.oceanFlora;
const grassSpread: string[] = [];
const kelpGrow: string[] = [];
let crops = 0;
let saplings = 0;

// Same square tickRandomBlocks samples: px + floor((rng*2-1)*R) ∈ [px-R, px+R-1].
for (let dx = -RANDOM_TICK_RADIUS; dx < RANDOM_TICK_RADIUS; dx += 1) {
  for (let dz = -RANDOM_TICK_RADIUS; dz < RANDOM_TICK_RADIUS; dz += 1) {
    const x = px + dx;
    const z = pz + dz;
    if (!world.inBounds(x, 0, z)) continue;
    const y = world.highestSolidY(x, z);
    const top = world.get(x, y, z) as BlockId;

    if (top === BlockId.Dirt) {
      for (const [nx, nz] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) {
        const ny = world.highestSolidY(x + nx, z + nz);
        if (world.get(x + nx, ny, z + nz) === BlockId.Grass) {
          grassSpread.push(`(${x},${y},${z})`);
          break;
        }
      }
    } else if (top === BlockId.Kelp) {
      let height = 1;
      while (world.get(x, y - height, z) === BlockId.Kelp) height += 1;
      if (height < kelpMaxHeight) {
        let clear = true;
        for (let dy = 1; dy <= kelpSurfaceClearance + 1; dy += 1) {
          if (world.get(x, y + dy, z) !== BlockId.Water) clear = false;
        }
        if (clear) kelpGrow.push(`(${x},${y},${z}) h=${height}`);
      }
    } else if (top === BlockId.Sapling) saplings += 1;
    else if (top >= BlockId.WheatStage0 && top <= BlockId.WheatStage2) crops += 1;
  }
}

const columns = (2 * RANDOM_TICK_RADIUS) ** 2;
console.log(`scanned ${columns} columns in the random-tick square`);
console.log(`grass-spread candidates (exposed dirt beside grass): ${grassSpread.length}`);
if (grassSpread.length) console.log("  " + grassSpread.slice(0, 10).join(" "));
console.log(`kelp-growth candidates (growable stalks): ${kelpGrow.length}`);
if (kelpGrow.length) console.log("  " + kelpGrow.slice(0, 10).join(" "));
console.log(`crops: ${crops}, saplings: ${saplings}`);

const pPerPass =
  1 -
  Math.pow(1 - GRASS_SPREAD_CHANCE / columns, RANDOM_TICK_SAMPLES * grassSpread.length) *
    Math.pow(1 - KELP_GROWTH_CHANCE / columns, RANDOM_TICK_SAMPLES * kelpGrow.length);
console.log(`≈P(≥1 edit) per 0.5s random-tick pass: ${(pPerPass * 100).toFixed(2)}%`);
console.log(`≈P over a 10s boot window (20 passes): ${((1 - Math.pow(1 - pPerPass, 20)) * 100).toFixed(1)}%`);

